using System.Collections.Generic;
using System.Text;
using FastMediatR.Generator.Models;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace FastMediatR.Generator.Emitters;

/// <summary>
/// Emits <c>FastMediatR.Generated.FastMediatRGeneratedRegistration</c> — a static class
/// with a <c>Register(IServiceCollection)</c> method that wires every discovered handler
/// and the dispatcher itself into DI without reflection.
/// </summary>
internal static class RegistrationEmitter
{
    /// <summary>Generated file hint name (used by <c>AddSource</c>).</summary>
    public const string HintName = "FastMediatRGeneratedRegistration.g.cs";

    /// <summary>
    /// Generates the DI registration source and adds it to the compilation.
    /// </summary>
    /// <param name="context">Source production context.</param>
    /// <param name="discovery">Aggregated discovery result.</param>
    public static void Emit(SourceProductionContext context, DiscoveryResult discovery)
    {
        context.AddSource(HintName, SourceText.From(BuildRegistration(discovery), Encoding.UTF8));
    }

    /// <summary>Builds the full registration source text.</summary>
    /// <param name="discovery">Aggregated discovery result.</param>
    /// <returns>Generated C# source code as a string.</returns>
    private static string BuildRegistration(DiscoveryResult discovery)
    {
        var sb = new StringBuilder();

        sb.AppendLine("// <auto-generated/>");
        sb.AppendLine("// FastMediatR source generator — DI registration");
        sb.AppendLine("#nullable enable");
        sb.AppendLine();
        sb.AppendLine("using System;");
        sb.AppendLine("using Microsoft.Extensions.DependencyInjection;");
        sb.AppendLine("using Microsoft.Extensions.DependencyInjection.Extensions;");
        sb.AppendLine();
        sb.AppendLine("namespace FastMediatR.Generated;");
        sb.AppendLine();
        sb.AppendLine("/// <summary>");
        sb.AppendLine("/// Source-generated DI registration for FastMediatR handlers.");
        sb.AppendLine("/// Called automatically by <c>AddFastMediatR</c>.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("[global::System.CodeDom.Compiler.GeneratedCode(\"FastMediatR.Generator\", \"1.0.0\")]");
        sb.AppendLine("internal static class FastMediatRGeneratedRegistration");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>");
        sb.AppendLine("    /// Registers all discovered FastMediatR handlers and the generated dispatcher.");
        sb.AppendLine("    /// </summary>");
        sb.AppendLine("    /// <param name=\"services\">The DI service collection to register into.</param>");
        sb.AppendLine("    /// <returns>The same <paramref name=\"services\"/> for chaining.</returns>");
        sb.AppendLine("    public static IServiceCollection Register(IServiceCollection services)");
        sb.AppendLine("    {");
        sb.AppendLine("        ArgumentNullException.ThrowIfNull(services);");
        sb.AppendLine();
        sb.AppendLine("        // Dispatcher — registered as all three entry-point interfaces.");
        sb.AppendLine("        services.TryAddScoped<FastMediatRDispatcher>();");
        sb.AppendLine("        services.TryAddScoped<global::FastMediatR.ISender>(sp => sp.GetRequiredService<FastMediatRDispatcher>());");
        sb.AppendLine("        services.TryAddScoped<global::FastMediatR.IPublisher>(sp => sp.GetRequiredService<FastMediatRDispatcher>());");
        sb.AppendLine("        services.TryAddScoped<global::FastMediatR.IMediator>(sp => sp.GetRequiredService<FastMediatRDispatcher>());");
        sb.AppendLine();

        // Request handlers
        if (discovery.RequestHandlers.Count > 0)
        {
            sb.AppendLine("        // Request handlers");

            // Deduplicate: a handler might implement multiple IRequestHandler<,> overloads;
            // only register the concrete type once.
            var registeredHandlers = new HashSet<string>();

            foreach (RequestHandlerInfo handler in discovery.RequestHandlers)
            {
                if (!registeredHandlers.Add(handler.HandlerFullyQualifiedName))
                {
                    continue;
                }

                string registrationMethod = LifetimeToRegistrationMethod(handler.LifetimeOverride);
                sb.AppendLine($"        services.{registrationMethod}<{handler.HandlerFullyQualifiedName}>();");
            }

            sb.AppendLine();
        }

        // Notification handlers
        if (discovery.NotificationHandlers.Count > 0)
        {
            sb.AppendLine("        // Notification handlers");

            var registeredHandlers = new HashSet<string>();

            foreach (NotificationHandlerInfo handler in discovery.NotificationHandlers)
            {
                if (!registeredHandlers.Add(handler.HandlerFullyQualifiedName))
                {
                    continue;
                }

                string registrationMethod = LifetimeToRegistrationMethod(handler.LifetimeOverride);
                sb.AppendLine($"        services.{registrationMethod}<{handler.HandlerFullyQualifiedName}>();");
            }

            sb.AppendLine();
        }

        sb.AppendLine("        return services;");
        sb.AppendLine("    }");
        sb.AppendLine("}");

        return sb.ToString();
    }

    /// <summary>
    /// Maps a <see cref="HandlerLifetime"/> (or its absence, meaning "use default Scoped") to the
    /// corresponding <c>IServiceCollection</c> extension method name.
    /// </summary>
    /// <param name="lifetime">Lifetime override, or <see langword="null"/> for the Scoped default.</param>
    /// <returns>The <c>TryAdd*</c> method name to emit.</returns>
    private static string LifetimeToRegistrationMethod(HandlerLifetime? lifetime) =>
        lifetime switch
        {
            HandlerLifetime.Singleton => "TryAddSingleton",
            HandlerLifetime.Transient => "TryAddTransient",
            _ => "TryAddScoped",
        };
}
